const https = require('https');
const fs = require('fs');

const HOST = 'ibnkmbcnkrvwdtrjmcel.supabase.co';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImlibmttYmNua3J2d2R0cmptY2VsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4OTExNDc4MCwiZXhwIjoyMTA0NjkwNzgwfQ.DwRIy8-ktRewOdswssnA-oC_b4TVLa0jSrLmjkXIS40';
const BOT_TOKEN = '8962981367:AAGlEBTQO4d27WEl_AG10z0taaSQfRyAiSw';

function getSupabase(reqPath) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'GET',
      headers: { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

function patchSupabase(reqPath, body) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(body);
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'PATCH',
      headers: {
        'apikey': SERVICE_KEY,
        'Authorization': 'Bearer ' + SERVICE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation'
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

function sendTelegram(chatId, text, buttons) {
  return new Promise((resolve) => {
    const payload = {
      chat_id: chatId,
      text: text,
      parse_mode: 'HTML'
    };
    if (buttons) {
      payload.reply_markup = { inline_keyboard: buttons };
    }
    const postData = JSON.stringify(payload);
    const req = https.request({
      hostname: 'api.telegram.org',
      port: 443,
      path: '/bot' + BOT_TOKEN + '/sendMessage',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    }, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve({ ok: res.statusCode === 200 }));
    });
    req.on('error', err => resolve({ ok: false, error: err.message }));
    req.write(postData);
    req.end();
  });
}

// 1. Calcular fecha objetivo (si es viernes salta 3 días al lunes, si es sábado suma 2)
const hoy = new Date();
const diaSemana = hoy.getDay(); // 5 = viernes, 6 = sábado
const diasASumar = (diaSemana === 5) ? 3 : ((diaSemana === 6) ? 2 : 1);

const manana = new Date();
manana.setDate(hoy.getDate() + diasASumar);
const mananaStr = manana.toISOString().slice(0, 10);
const etiquetaDia = (diaSemana === 5 || diaSemana === 6) ? 'del próximo lunes' : 'de mañana';

// 2. Consultar citas, pacientes y doctores en Supabase
const citas = await getSupabase(`/rest/v1/clinica_citas?fecha_hora_inicio=gte.${mananaStr}T00:00:00Z&fecha_hora_inicio=lte.${mananaStr}T23:59:59Z&estado=neq.CANCELADA&select=*`);
const [pacientes, doctores] = await Promise.all([
  getSupabase('/rest/v1/clinica_pacientes?select=*'),
  getSupabase('/rest/v1/clinica_doctores?select=*')
]);

const pacMap = {};
(Array.isArray(pacientes) ? pacientes : []).forEach(p => pacMap[p.id] = p);
const docMap = {};
(Array.isArray(doctores) ? doctores : []).forEach(d => docMap[d.id] = d);

const resultados = [];

if (Array.isArray(citas)) {
  for (const c of citas) {
    // // if (c.recordatorio_24h_enviado) continue; // Permitir reenvio en demo // Permitir reenvio en demo

    const pac = pacMap[c.paciente_id] || {};
    const doc = docMap[c.doctor_id] || {};
    const hora = c.fecha_hora_inicio ? c.fecha_hora_inicio.slice(11, 16) : 'Hora a confirmar';

    const texto = `👋 ¡Hola <b>${pac.nombre || 'Paciente'}</b>! Te recordamos tu cita ${etiquetaDia}:\n\n` +
      `📅 <b>Fecha:</b> ${mananaStr}\n` +
      `⏰ <b>Hora:</b> ${hora} hs\n` +
      `🩺 <b>Especialista:</b> ${doc.nombre_completo || 'Doctor/a'}\n` +
      `🦷 <b>Especialidad:</b> ${c.especialidad || 'Odontología'}\n` +
      `📍 <b>Lugar:</b> Clínica Dental Neclatrony (C/ Gran Vía 45)\n\n` +
      `¿Nos confirmas tu asistencia? Por favor presiona uno de los botones de abajo o responde a este chat.`;

    const buttons = [
      [
        { text: '✅ Confirmar Asistencia', callback_data: `CONFIRMAR_CITA:${c.erp_cita_id || c.id}` },
        { text: '❌ Cancelar Turno', callback_data: `CANCELAR_CITA:${c.erp_cita_id || c.id}` }
      ]
    ];

    let tgEnviado = false;
    if (pac.telegram_chat_id) {
      const res = await sendTelegram(pac.telegram_chat_id, texto, buttons);
      tgEnviado = res.ok;
    }

    if (tgEnviado) {
      await patchSupabase(`/rest/v1/clinica_citas?id=eq.${c.id}`, {
        recordatorio_24h_enviado: true,
        // estado permanece PROGRAMADA hasta que confirme
        fecha_actualizacion: new Date().toISOString()
      });
    }

    resultados.push({
      cita_id: c.id,
      erp_cita_id: c.erp_cita_id,
      paciente: pac.nombre,
      telegram_chat_id: pac.telegram_chat_id || 'NO_REGISTRADO',
      telegram_enviado: tgEnviado,
      estado_nuevo: c.estado
    });
  }
}

return [{ json: { total_procesados: resultados.length, fecha_manana: mananaStr, detalle: resultados } }];

